use vstd::prelude::*;

verus! {
    /// Given n ≥ 1, constructs a sequence of length n over {'a','b'}
    /// such that for all i with 0 ≤ i ≤ n−3, seq[i] != seq[i+2].
    /// We do so by repeating the block "aabb", which uses no 'c'.
    fn solve(n: i8) -> (result: Vec<char>)
        requires
            n >= 1,
        ensures
            result.len() == n as usize,
        ensures
            // distance-2 characters are always different
            forall |k: usize| k + 2 < result.len() ==> result[k] != result[k+2],
        ensures
            // only 'a' or 'b' are used
            forall |k: usize| k < result.len() ==> result[k] == 'a' || result[k] == 'b'
    {
        let nn: usize = n as usize;
        let mut result: Vec<char> = Vec::new();
        result.reserve(nn);

        let mut i: usize = 0;
        while i < nn
            invariant
                0 <= i && i <= nn,
                result.len() == i,
                // preserved distance-2 inequality for already filled prefix
                forall |j: usize| j + 2 < result.len() ==> result[j] != result[j+2],
                // preserved alphabet restriction
                forall |j: usize| j < result.len() ==> result[j] == 'a' || result[j] == 'b',
            decreases
                nn - i
        {
            // We cycle through 0,1 → 'a'; 2,3 → 'b' mod 4 ⇒ block "aabb"
            let rem = i % 4;
            let ch = if rem == 0 || rem == 1 { 'a' } else { 'b' };

            result.push(ch);

            // Verify the new push preserves the distance-2 inequality
            if i >= 2 {
                assert(result[i] != result[i - 2]);
            }
            // Verify we only used 'a' or 'b'
            assert(ch == 'a' || ch == 'b');

            i += 1;
        }

        result
    }
}

fn main() {
    // example
    let v = solve(7);
    // v might be ['a','a','b','b','a','a','b']
    assert(v.len() == 7);
}